cat > merge.py <<'EOF'
import json, pandas as pd
from datetime import datetime

def norm_date(v):
    if v is None or (isinstance(v, float) and pd.isna(v)): return None
    if hasattr(v, "strftime"): return v.strftime("%Y-%m-%d")
    s = str(v).strip()
    for f in ("%Y-%m-%d","%Y/%m/%d","%m/%d/%Y","%d-%m-%Y","%Y-%m-%dT%H:%M:%S","%Y-%m-%d %H:%M:%S"):
        try: return datetime.strptime(s, f).strftime("%Y-%m-%d")
        except ValueError: pass
    return pd.to_datetime(s).strftime("%Y-%m-%d")

MAP = {"user_id":"user_id","id":"user_id","userId":"user_id",
       "email":"email","email_address":"email",
       "full_name":"name","name":"name","userName":"name",
       "registration_date":"created_date","created_at":"created_date","joined":"created_date",
       "status":"status"}
BOOL_STATUS = ("is_active","active")

def to_bool(v):
    if isinstance(v, str): return v.strip().lower() in ("true","1","yes","y","t")
    return bool(v)

def normalize(records):
    out = {}
    for r in records:
        rec = {}
        for k, v in r.items():
            if k in MAP:
                rec[MAP[k]] = v
        if "status" not in rec:
            for b in BOOL_STATUS:
                if b in r and r[b] is not None and not (isinstance(r[b], float) and pd.isna(r[b])):
                    rec["status"] = "active" if to_bool(r[b]) else "inactive"
                    break
        for k in list(rec):
            v = rec[k]
            if v is None or (not isinstance(v, str) and pd.isna(v)): rec[k] = None
        if rec.get("user_id") is None: continue
        rec["user_id"] = int(rec["user_id"])
        if rec.get("created_date") is not None: rec["created_date"] = norm_date(rec["created_date"])
        for k in ("name","email","status"):
            if rec.get(k) is not None: rec[k] = str(rec[k]).strip()
        out[rec["user_id"]] = rec
    return out

a = normalize(json.load(open("/data/source_a/users.json")))
b = normalize(pd.read_csv("/data/source_b/users.csv", dtype=str).to_dict("records"))
c = normalize(pd.read_parquet("/data/source_c/users.parquet").to_dict("records"))
sources = [("source_a", a), ("source_b", b), ("source_c", c)]
FIELDS = ["name","email","created_date","status"]

rows, conflicts = [], []
for uid in sorted(set(a) | set(b) | set(c)):
    row = {"user_id": uid}
    for f in FIELDS:
        vals = {s: d[uid].get(f) for s, d in sources if uid in d and d[uid].get(f) is not None}
        sel = next(iter(vals.values()), None)
        row[f] = sel
        if len(set(vals.values())) > 1:
            conflicts.append({"user_id": uid, "field": f, "values": vals, "selected": sel})
    rows.append(row)

df = pd.DataFrame(rows, columns=["user_id"] + FIELDS)
df["user_id"] = df["user_id"].astype("int64")
for f in FIELDS: df[f] = df[f].astype(object)
df.to_parquet("/app/merged_users.parquet", index=False)
json.dump({"total_conflicts": len(conflicts), "conflicts": conflicts}, open("/app/conflicts.json","w"), indent=2)
print(df); print(df.dtypes); print(json.dumps(conflicts, indent=1))
EOF
./envrun 'cat > /app/merge.py' < merge.py && ./envrun 'python3 /app/merge.py && python3 -c "import pyarrow.parquet as pq; print(pq.read_schema(\"/app/merged_users.parquet\"))"'
